import"./hoisted.BQh-Wvb4.js";const e=document.getElementById("contact-form"),t=document.getElementById("form-status");e?.addEventListener("submit",async n=>{if(n.preventDefault(),!!t){t.style.display="block",t.textContent="Sending...";try{const o=new FormData(e);(await fetch("/api/contact",{method:"POST",body:JSON.stringify(Object.fromEntries(o)),headers:{"Content-Type":"application/json"}})).ok?(t.textContent="Thank you. We will get back to you within one business day.",e.reset()):t.textContent="Something went wrong. Please email hello@annai.sg directly."}catch{t.textContent="Something went wrong. Please email hello@annai.sg directly."}}});
